/* D06 Scripts: one reachable page flow, durable outcomes and local code scrolling. */
.pine{min-height:0;overflow:auto}
.pine .pine-main{min-height:480px;flex:1 0 480px!important}
.pine .pine-topbar{flex:none;flex-wrap:wrap;gap:8px;padding:12px 16px}
.pine .pine-topbar .page-title{font-size:18px;font-weight:700}
.pine-script-picker{min-width:0;max-width:min(100%,360px)}
.pine-script-picker>.pair{max-width:100%;height:44px}
.pine-script-picker>.pair b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pine-script-picker>.pop{top:48px;left:0;min-width:240px;max-width:min(360px,calc(100vw - 32px))}
.pine-script-picker .menu-row{width:100%;min-height:44px;text-align:left;gap:8px}
.pine-action-reason{flex-basis:100%;margin:0;color:var(--muted);font:12px/1.5 var(--font-ui)}
.pine .btn,.pine .ai,.pine .editor-actions .tbtn{min-height:44px;height:auto}
.pine button:focus-visible,.pine a:focus-visible{outline:2px solid var(--brand-2);outline-offset:2px}
.pine .script-row{width:100%;min-height:58px;text-align:left;border:1px solid transparent;background:transparent}
.pine .script-row.on{border-color:var(--line-3);background:var(--panel-2)}
.pine .script-row .meta>span{overflow-wrap:anywhere}
.pine .side-sec h4{color:var(--text-2);font-size:12px;line-height:1.4}
.pine .stepper button{width:44px;height:44px}
.pine .inp-row{gap:12px;overflow-wrap:anywhere}
.pine .editor-pane{min-height:420px}
.pine .editor-head{flex:none;min-height:52px;height:auto;padding:8px 14px;flex-wrap:wrap}
.pine-step{color:var(--muted);font:600 11px/1.4 var(--font-ui)}
.pine .editor{min-height:240px;max-height:65svh;overscroll-behavior:contain}
.pine .code-wrap{min-width:max-content}
.pine .code-wrap textarea{width:100%;height:100%}
.pine .editor:focus-within{outline:2px solid var(--brand-2);outline-offset:-2px}
.pine .console{height:auto;min-height:130px;max-height:240px;padding:12px 16px}
.pine-console-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;font:600 12px/1.5 var(--font-ui);color:var(--text)}
.pine-dirty{color:var(--warn)}
.pine-diagnostic-scope{margin:6px 0;color:var(--muted);font:12px/1.5 var(--font-ui)}
.pine-save-outcome{flex:none;display:flex;align-items:flex-start;flex-wrap:wrap;gap:14px;padding:16px;margin:16px;border:1px solid var(--line-3);border-radius:var(--r-md);background:var(--panel-2)}
.pine-outcome-copy{flex:1;min-width:200px}
.pine-outcome-copy strong{font:650 14px/1.4 var(--font-ui)}
.pine-outcome-copy p,.pine-save-comparison>p{margin:5px 0 0;font:13px/1.6 var(--font-ui);color:var(--text-2)}
.pine-outcome-copy small{display:block;margin-top:6px;color:var(--muted);font:11px/1.5 var(--font-code);overflow-wrap:anywhere}
.pine-save-outcome[data-save-state="unknown"] .pine-outcome-copy strong,.pine-save-outcome[data-save-state="conflict"] .pine-outcome-copy strong,.pine-save-outcome[data-save-state="different"] .pine-outcome-copy strong{color:var(--warn)}
.pine-save-comparison{width:100%}
.pine-version-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.pine-version-grid>section{min-width:0;padding:12px;border:1px solid var(--line);border-radius:var(--r);background:var(--panel)}
.pine-version-grid h3{font:650 12px/1.5 var(--font-ui);color:var(--muted);margin:0 0 5px}
.pine-version-grid b{font-size:13px;overflow-wrap:anywhere}
.pine-version-grid pre{max-height:180px;overflow:auto;overscroll-behavior:contain;font:11px/1.6 var(--font-code);white-space:pre}
.pine-outcome-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
@media(max-width:860px){
 .pine .pine-topbar{gap:8px;padding:12px}
 .pine .pine-topbar>.page-title{flex-basis:100%}
 .pine .pine-topbar>.spacer{display:none}
 .pine .pine-script-picker{flex:1 1 100%;max-width:100%}
 .pine-script-picker>.pair{width:100%;justify-content:space-between}
 .pine .pine-topbar>[data-script-save],.pine .pine-topbar>[data-script-add]{flex:1 1 40%;margin:0!important}
 .pine .pine-main{flex:0 0 auto!important;min-height:0;height:auto;max-height:none;overflow:visible}
 .pine .editor-pane{flex:none;height:auto;min-height:0}
 .pine .editor{flex:none;height:36svh;min-height:240px;max-height:360px}
 .pine .pine-side{max-height:none;overflow:visible}
 .pine .console{min-height:140px;max-height:none}
 .pine-save-outcome{margin:12px;padding:12px}
 .pine-outcome-copy{min-width:0;flex-basis:100%}
 .pine-version-grid{grid-template-columns:minmax(0,1fr)}
 .pine-unsaved{max-height:calc(100svh - 32px);overflow:auto}
 .pine-unsaved-acts{flex-wrap:wrap}
 .pine-unsaved-acts button{min-height:44px}
 .pine-unsaved-acts>div{display:none}
}

.pine .pine-topbar>[data-script-add]{font-size:13px!important;line-height:1.4}
.pine button:disabled{opacity:.55;cursor:not-allowed}
.pine .script-row .meta small{font-size:11px;line-height:1.5}

